22	namespace hixl {
23	namespace {
24	Status CheckTransferOpDescs(const std::vector<TransferOpDesc> &op_descs) {
25	  for (const auto &desc : op_descs) {
26	    auto local_addr = reinterpret_cast<void *>(desc.local_addr);
27	    auto remote_addr = reinterpret_cast<void *>(desc.remote_addr);
28	    HIXL_CHK_BOOL_RET_STATUS(local_addr != nullptr, PARAM_INVALID, "local addr of desc can not be null.");
29	    HIXL_CHK_BOOL_RET_STATUS(remote_addr != nullptr, PARAM_INVALID, "remote addr of desc can not be null.");
30	  }
31	  return SUCCESS;
32	}
33	}  // namespace
34	
35	class Hixl::HixlImpl {
36	 public:
37	  explicit HixlImpl(const AscendString &local_engine) : local_engine_(local_engine.GetString()) {}
38	  ~HixlImpl() = default;
39	
40	  Status Initialize(const std::map<AscendString, AscendString> &options);
41	
42	  void Finalize();
43	
44	  Status RegisterMem(const MemDesc &mem, MemType type, MemHandle &mem_handle);
45	
46	  Status DeregisterMem(MemHandle mem_handle);
47	
48	  Status Connect(const AscendString &remote_engine, int32_t timeout_in_millis = 1000);
49	
50	  Status Disconnect(const AscendString &remote_engine, int32_t timeout_in_millis = 1000);
51	
52	  Status ConnectAsync(const AscendString &remote_engine, int32_t timeout_in_millis = 1000);
53	
54	  Status DisconnectAsync(const AscendString &remote_engine, int32_t timeout_in_millis = 1000);
55	
56	  Status GetAsyncConnectStatus(const AscendString &remote_engine, AsyncConnectStatus &status) const;
57	
58	  Status GetAsyncConnectStatus(std::map<AscendString, AsyncConnectStatus> &statuses) const;
59	
60	  Status TransferSync(const AscendString &remote_engine, TransferOp operation,
61	                      const std::vector<TransferOpDesc> &op_descs, int32_t timeout_in_millis = 1000);
62	
63	  Status TransferAsync(const AscendString &remote_engine, TransferOp operation,
64	                       const std::vector<TransferOpDesc> &op_descs, const TransferArgs &optional_args,
65	                       TransferReq &req);
66	
67	  Status GetTransferStatus(const TransferReq &req, TransferStatus &status);
68	
69	  Status GetTransferStatus(const GetTransferStatusArgs &args, std::vector<TransferResult> &results);
70	
71	  Status SendNotify(const AscendString &remote_engine, const NotifyDesc &notify, uint32_t timeout_in_millis);
72	
73	  Status GetNotifies(std::vector<NotifyDesc> &notifies);
74	
75	 private:
76	  std::mutex mutex_;
77	  std::string local_engine_;
78	  std::unique_ptr<Engine> engine_ = nullptr;
79	  ConnectPoolExecutor connect_pool_executor_;
80	};
81	
82	Status Hixl::HixlImpl::Initialize(const std::map<AscendString, AscendString> &options) {
83	  std::lock_guard<std::mutex> lk(mutex_);
84	  if (engine_ != nullptr) {
85	    HIXL_CHK_BOOL_RET_SPECIAL_STATUS(engine_->IsInitialized(), SUCCESS, "Already initialized");
86	  }
87	  HixlOptions parsed_options;
88	  engine_ = hixl::EngineFactory::CreateEngine(local_engine_, options, parsed_options);
89	  HIXL_CHECK_NOTNULL(engine_, "[HixlEngine] Created engine is null, please check your parameters! local_engine:%s",
90	                     local_engine_.c_str());
91	  HIXL_CHK_STATUS_RET(engine_->Initialize(parsed_options), "Failed to initialize Hixl.");
92	  Status ret = connect_pool_executor_.Initialize(parsed_options);
93	  if (ret != SUCCESS) {
94	    engine_->Finalize();
95	    engine_.reset();
96	    HIXL_LOGE(ret, "Failed to initialize ConnectPoolExecutor.");
97	    return ret;
98	  }
99	  return SUCCESS;
100	}
101	
102	void Hixl::HixlImpl::Finalize() {
103	  if (engine_ == nullptr) {
104	    HIXL_LOGE(FAILED, "engine is nullptr, check engine init");
105	    return;
106	  }
107	  connect_pool_executor_.Shutdown();
108	  engine_->Finalize();
109	  engine_.reset();
110	}
111	
112	Status Hixl::HixlImpl::RegisterMem(const MemDesc &mem, MemType type, MemHandle &mem_handle) {
113	  HIXL_CHK_BOOL_RET_STATUS(engine_ != nullptr, FAILED, "engine is nullptr, check engine init");
114	  HIXL_CHK_BOOL_RET_STATUS(engine_->IsInitialized(), FAILED, "Hixl is not initialized");
115	  HIXL_CHK_BOOL_RET_STATUS(reinterpret_cast<void *>(mem.addr) != nullptr, PARAM_INVALID, "mem.addr can not be null");
116	  HIXL_CHK_STATUS_RET(engine_->RegisterMem(mem, type, mem_handle), "Failed to register mem");
117	  return SUCCESS;
118	}
119	
120	Status Hixl::HixlImpl::DeregisterMem(MemHandle mem_handle) {
121	  HIXL_CHK_BOOL_RET_STATUS(engine_ != nullptr, FAILED, "engine is nullptr, check engine init");
122	  HIXL_CHK_BOOL_RET_STATUS(engine_->IsInitialized(), FAILED, "Hixl is not initialized");
123	  HIXL_CHK_BOOL_RET_STATUS(mem_handle != nullptr, PARAM_INVALID, "mem_handle can not be null");
124	  HIXL_CHK_STATUS_RET(engine_->DeregisterMem(mem_handle), "Failed to deregister mem");
125	  return SUCCESS;
126	}
127	
128	Status Hixl::HixlImpl::Connect(const AscendString &remote_engine, int32_t timeout_in_millis) {
129	  HIXL_CHK_BOOL_RET_STATUS(engine_ != nullptr, FAILED, "engine is nullptr, check engine init");
130	  HIXL_CHK_BOOL_RET_STATUS(engine_->IsInitialized(), FAILED, "Hixl is not initialized");
131	  HIXL_CHK_STATUS_RET(engine_->Connect(remote_engine, timeout_in_millis), "Failed to connect");
132	  return SUCCESS;
133	}
134	
135	Status Hixl::HixlImpl::Disconnect(const AscendString &remote_engine, int32_t timeout_in_millis) {
136	  HIXL_CHK_BOOL_RET_STATUS(engine_ != nullptr, FAILED, "engine is nullptr, check engine init");
137	  HIXL_CHK_BOOL_RET_STATUS(engine_->IsInitialized(), FAILED, "Hixl is not initialized");
138	  HIXL_CHK_STATUS_RET(engine_->Disconnect(remote_engine, timeout_in_millis), "Failed to disconnect");
139	  return SUCCESS;
140	}
141	
142	Status Hixl::HixlImpl::ConnectAsync(const AscendString &remote_engine, int32_t timeout_in_millis) {
143	  HIXL_CHK_BOOL_RET_STATUS(engine_ != nullptr, FAILED, "engine is nullptr, check engine init");
144	  HIXL_CHK_BOOL_RET_STATUS(engine_->IsInitialized(), FAILED, "Hixl is not initialized");
145	  auto task = [this, remote_engine, timeout_in_millis]() {
146	    HIXL_LOGI("connect async to %s %d start", remote_engine.GetString(), timeout_in_millis);
147	    Status ret = engine_->Connect(remote_engine, timeout_in_millis);
148	    const auto status = (ret == SUCCESS || ret == ALREADY_CONNECTED) ? AsyncConnectStatus::CONNECTED
149	                                                                     : AsyncConnectStatus::CONNECT_FAILED;
150	    connect_pool_executor_.SetStatus(remote_engine, status);
151	    HIXL_LOGI("connect async to %s %d ret %d status %d", remote_engine.GetString(), timeout_in_millis, ret, status);
152	  };
153	  return connect_pool_executor_.Submit(task, remote_engine, true);
154	}
