157	  HIXL_CHK_BOOL_RET_STATUS(engine_ != nullptr, FAILED, "engine is nullptr, check engine init");
158	  HIXL_CHK_BOOL_RET_STATUS(engine_->IsInitialized(), FAILED, "Hixl is not initialized");
159	  auto task = [this, remote_engine, timeout_in_millis]() {
160	    HIXL_LOGI("disconnect async to %s %d start", remote_engine.GetString(), timeout_in_millis);
161	    Status ret = engine_->Disconnect(remote_engine, timeout_in_millis);
162	    connect_pool_executor_.SetStatus(remote_engine, AsyncConnectStatus::NOT_CONNECT);
163	    HIXL_LOGI("disconnect async to %s %d ret %d", remote_engine.GetString(), timeout_in_millis, ret);
164	  };
165	  return connect_pool_executor_.Submit(task, remote_engine, false);
