57	template <typename T>
58	Status ParseIntegerFieldInRange(const nlohmann::json &json, const IntegerFieldRange &range, std::optional<T> &target) {
59	  if (!json.contains(range.name)) {
60	    return SUCCESS;
61	  }
62	
63	  int64_t val = JsonToNumber<int64_t>(json.at(range.name));
64	  HIXL_CHK_BOOL_RET_STATUS(val >= range.min_value && val <= range.max_value, PARAM_INVALID,
65	                           "%s must be in [%lld, %lld]%s, got %lld", range.name,
66	                           static_cast<long long>(range.min_value), static_cast<long long>(range.max_value), range.unit,
67	                           static_cast<long long>(val));
68	  target = static_cast<T>(val);
69	  return SUCCESS;
70	}
