72	Status ReadLocalCommResFile(const char *resolved_path, std::string &content) {
73	  constexpr int kOpenFlags = O_RDONLY | O_CLOEXEC | O_NONBLOCK | O_NOFOLLOW;
74	  int fd = open(resolved_path, kOpenFlags);
75	  HIXL_CHK_BOOL_RET_STATUS(fd >= 0, PARAM_INVALID,
76	                           "Call api:open failed, path:%s, flags:%d, ret:%d, errno:%d, error:%s", resolved_path,
77	                           kOpenFlags, fd, errno, strerror(errno));
78	  HIXL_MAKE_GUARD(close_fd, ([fd]() { (void)close(fd); }));
79	
80	  struct stat file_stat {};
81	  int stat_ret = fstat(fd, &file_stat);
82	  HIXL_CHK_BOOL_RET_STATUS(stat_ret == 0, PARAM_INVALID, "Call api:fstat failed, path:%s, ret:%d, errno:%d, error:%s",
83	                           resolved_path, stat_ret, errno, strerror(errno));
84	  HIXL_CHK_BOOL_RET_STATUS(S_ISREG(file_stat.st_mode), PARAM_INVALID,
85	                           "local_comm_res_path must reference a regular file, path:%s, mode:%o", resolved_path,
86	                           static_cast<unsigned int>(file_stat.st_mode));
87	  HIXL_CHK_BOOL_RET_STATUS(
88	      file_stat.st_size > 0 && static_cast<uint64_t>(file_stat.st_size) <= kMaxLocalCommResFileSizeBytes, PARAM_INVALID,
89	      "local_comm_res_path file size is invalid, path:%s, size:%lld bytes, valid range:[1, %zu] bytes", resolved_path,
90	      static_cast<long long>(file_stat.st_size), kMaxLocalCommResFileSizeBytes);
91	
92	  const size_t file_size = static_cast<size_t>(file_stat.st_size);
93	  content.resize(file_size);
94	  size_t read_size = 0U;
95	  while (read_size < file_size) {
96	    ssize_t read_ret = read(fd, content.data() + read_size, file_size - read_size);
97	    if (read_ret < 0) {
98	      int read_errno = errno;
99	      if (read_errno == EINTR) {
100	        continue;
101	      }
102	      HIXL_CHK_BOOL_RET_STATUS(false, PARAM_INVALID,
103	                               "Call api:read failed, path:%s, ret:%zd, read_size:%zu bytes, "
104	                               "expected_size:%zu bytes, errno:%d, error:%s",
105	                               resolved_path, read_ret, read_size, file_size, read_errno, strerror(read_errno));
106	    }
107	    HIXL_CHK_BOOL_RET_STATUS(read_ret != 0, PARAM_INVALID,
108	                             "Call api:read reached unexpected EOF, path:%s, ret:%zd, read_size:%zu bytes, "
109	                             "expected_size:%zu bytes",
110	                             resolved_path, read_ret, read_size, file_size);
111	    read_size += static_cast<size_t>(read_ret);
112	  }
113	  return SUCCESS;
114	}
