126	  HIXL_CHK_STATUS_RET(ParseIntegerFieldInRange(json, stream_num_range, cfg.task_stream_num),
127	                      "Failed to parse fabric_memory.task_stream_num");
128	  if (json.contains("enable_aicpu_unfold")) {
129	    cfg.enable_aicpu_unfold = json.at("enable_aicpu_unfold").get<bool>();
130	  }
131	  return SUCCESS;
132	}
