134	Status ParseFabricMemoryConfig(const nlohmann::json &json, FabricMemoryConfig &cfg) {
135	  if (json.contains("fabric_memory") && json.at("fabric_memory").is_object()) {
136	    HIXL_CHK_STATUS_RET(ParseFabricMemoryFields(json.at("fabric_memory"), cfg),
137	                        "Failed to parse nested FabricMemoryConfig");
138	  }
139	  IntegerFieldRange capacity_range = {"fabric_memory.max_capacity", 1, static_cast<int64_t>(kMaxCapacityTB), " TB"};
140	  HIXL_CHK_STATUS_RET(ParseIntegerFieldInRange(json, capacity_range, cfg.max_capacity),
141	                      "Failed to parse fabric_memory.max_capacity");
142	  IntegerFieldRange start_addr_range = {"fabric_memory.start_address", static_cast<int64_t>(kMinFabricMemStartAddrTB),
143	                                        static_cast<int64_t>(kMaxFabricMemStartAddrTB), " TB"};
144	  HIXL_CHK_STATUS_RET(ParseIntegerFieldInRange(json, start_addr_range, cfg.start_address),
145	                      "Failed to parse fabric_memory.start_address");
146	  IntegerFieldRange stream_num_range = {"fabric_memory.task_stream_num", static_cast<int64_t>(kMinTaskStreamNum),
147	                                        static_cast<int64_t>(kMaxTaskStreamNum), ""};
148	  HIXL_CHK_STATUS_RET(ParseIntegerFieldInRange(json, stream_num_range, cfg.task_stream_num),
149	                      "Failed to parse fabric_memory.task_stream_num");
150	  if (json.contains("fabric_memory.enable_aicpu_unfold")) {
151	    cfg.enable_aicpu_unfold = json.at("fabric_memory.enable_aicpu_unfold").get<bool>();
152	  }
153	  if (cfg.enable_aicpu_unfold.value_or(true) && cfg.task_stream_num.has_value()) {
154	    HIXL_CHK_BOOL_RET_STATUS(*cfg.task_stream_num == 1U, PARAM_INVALID,
155	                             "aicpu_unfold mode only supports fabric_memory.task_stream_num=1, got %zu",
156	                             *cfg.task_stream_num);
157	  }
158	  return SUCCESS;
159	}
