212	Status HixlOptions::Parse(const std::map<AscendString, AscendString> &options, HixlOptions &result) {
213	  HIXL_LOGI("Start parsing options, total options count: %zu", options.size());
214	  for (const auto &pair : options) {
215	    HIXL_LOGI("  option key: \"%s\", value: \"%s\"", pair.first.GetString(), pair.second.GetString());
216	  }
217	  result.raw_options_ = options;
218	  for (const auto &pair : options) {
219	    result.parsed_keys_.insert(pair.first.GetString());
220	  }
221	  HIXL_CHK_STATUS_RET(result.ParseRdmaOptions(options), "Failed to parse RDMA options.");
222	  HIXL_CHK_STATUS_RET(result.ParseEndpointOptions(options), "Failed to parse endpoint options.");
223	  HIXL_CHK_STATUS_RET(result.ParseFabricMemOptions(options), "Failed to parse FabricMem options.");
224	  HIXL_CHK_STATUS_RET(result.ParseAutoConnectOptions(options), "Failed to parse AutoConnect options.");
225	  HIXL_CHK_STATUS_RET(result.ParseGlobalResourceConfig(options), "Failed to parse GlobalResourceConfig.");
226	  HIXL_CHK_STATUS_RET(result.ResolveLocalCommResFromFile(), "Failed to resolve LocalCommRes from file.");
227	  return SUCCESS;
228	}
