246	Status HixlOptions::ParseRdmaOptions(const std::map<AscendString, AscendString> &options) {
247	  std::string traffic_class_str;
248	  const auto &hixl_tc_it = options.find(hixl::OPTION_RDMA_TRAFFIC_CLASS);
249	  const auto &adxl_tc_it = options.find(adxl::OPTION_RDMA_TRAFFIC_CLASS);
250	  auto tc_it = (hixl_tc_it != options.cend()) ? hixl_tc_it : adxl_tc_it;
251	  if (tc_it != options.cend()) {
252	    traffic_class_str = tc_it->second.GetString();
253	  }
254	  if (traffic_class_str.empty()) {
255	    const char *env_ret = std::getenv("HCCL_RDMA_TC");
256	    if (env_ret != nullptr) {
257	      traffic_class_str = env_ret;
258	    }
259	  }
260	  if (!traffic_class_str.empty()) {
261	    int32_t traffic_class = 0;
262	    HIXL_CHK_STATUS_RET(ToNumber(traffic_class_str, traffic_class), "Traffic class is invalid, value = %s",
263	                        traffic_class_str.c_str());
264	    HIXL_CHK_BOOL_RET_STATUS(traffic_class >= kMinRdmaTrafficClass && traffic_class <= kMaxRdmaTrafficClass &&
265	                                 (traffic_class % kRdmaTrafficClassAlign == 0),
266	                             PARAM_INVALID,
267	                             "Traffic class is invalid, value = %d, must be between 0-255 and a multiple of 4",
268	                             traffic_class);
269	    rdma_traffic_class_ = static_cast<uint8_t>(traffic_class);
270	    HIXL_EVENT("Set rdma traffic class to %u", rdma_traffic_class_.value());
271	  }
272	
273	  std::string service_level_str;
274	  const auto &hixl_sl_it = options.find(hixl::OPTION_RDMA_SERVICE_LEVEL);
275	  const auto &adxl_sl_it = options.find(adxl::OPTION_RDMA_SERVICE_LEVEL);
276	  auto sl_it = (hixl_sl_it != options.cend()) ? hixl_sl_it : adxl_sl_it;
277	  if (sl_it != options.cend()) {
278	    service_level_str = sl_it->second.GetString();
279	  }
280	  if (service_level_str.empty()) {
281	    const char *env_ret = std::getenv("HCCL_RDMA_SL");
282	    if (env_ret != nullptr) {
283	      service_level_str = env_ret;
284	    }
285	  }
286	  if (!service_level_str.empty()) {
287	    int32_t service_level = 0;
288	    HIXL_CHK_STATUS_RET(ToNumber(service_level_str, service_level), "Service level is invalid, value = %s",
289	                        service_level_str.c_str());
290	    HIXL_CHK_BOOL_RET_STATUS(service_level >= kMinRdmaServiceLevel && service_level <= kMaxRdmaServiceLevel,
291	                             PARAM_INVALID, "service_level must be in [0, 7], value = %d", service_level);
292	    rdma_service_level_ = static_cast<uint8_t>(service_level);
293	    HIXL_EVENT("Set rdma service level to %u", rdma_service_level_.value());
294	  }
295	  return SUCCESS;
296	}
