298	Status HixlOptions::ParseEndpointOptions(const std::map<AscendString, AscendString> &options) {
299	  const auto &hixl_lcr_it = options.find(hixl::OPTION_LOCAL_COMM_RES);
300	  const auto &adxl_lcr_it = options.find(adxl::OPTION_LOCAL_COMM_RES);
301	  auto lcr_it = (hixl_lcr_it != options.cend()) ? hixl_lcr_it : adxl_lcr_it;
302	  if (lcr_it != options.cend()) {
303	    local_comm_res_ = std::string(lcr_it->second.GetString());
304	    HIXL_EVENT("ParseEndpointOptions success: local_comm_res=%s", local_comm_res_.value_or("").c_str());
305	  }
