311	  if (efm_it != options.end() && !std::string(efm_it->second.GetString()).empty()) {
312	    uint32_t enabled = 0U;
313	    HIXL_CHK_STATUS_RET(ToNumber(std::string(efm_it->second.GetString()), enabled), "%s is invalid, value = %s",
314	                        hixl::OPTION_ENABLE_USE_FABRIC_MEM, efm_it->second.GetString());
315	    HIXL_CHK_BOOL_RET_STATUS(enabled == 0U || enabled == 1U, PARAM_INVALID, "%s is invalid, should be zero or one.",
316	                             hixl::OPTION_ENABLE_USE_FABRIC_MEM);
317	    enable_fabric_mem_ = (enabled == 1U);
318	    HIXL_EVENT("ParseFabricMemOptions success: enable_fabric_mem=%d", enable_fabric_mem_.value());
