333	  HIXL_CHK_STATUS_RET(ToNumber(auto_connect_str, auto_connect), "%s is invalid, value = %s", hixl::OPTION_AUTO_CONNECT,
334	                      auto_connect_str.c_str());
335	  HIXL_CHK_BOOL_RET_STATUS(auto_connect == 0U || auto_connect == 1U, PARAM_INVALID,
336	                           "%s is invalid, should be zero or one.", hixl::OPTION_AUTO_CONNECT);
