342	Status HixlOptions::ParseGlobalResourceConfig(const std::string &config_str) {
343	  try {
344	    auto json = nlohmann::json::parse(config_str);
345	    if (!json.is_object()) {
346	      HIXL_LOGE(PARAM_INVALID, "GlobalResourceConfig must be a JSON object.");
347	      return PARAM_INVALID;
348	    }
349	    GlobalResourceConfig cfg{};
350	    HIXL_CHK_STATUS_RET(ParseGlobalResourceConfigJson(json, cfg), "Parse GlobalResourceConfig failed.");
351	    global_resource_config_ = std::move(cfg);
352	    return SUCCESS;
353	  } catch (const nlohmann::json::exception &e) {
354	    HIXL_LOGE(PARAM_INVALID, "Failed to parse GlobalResourceConfig json, exception:%s", e.what());
355	    return PARAM_INVALID;
356	  }
