361	  if (config_it == options.end()) {
362	    return SUCCESS;
363	  }
364	  std::string config_str = config_it->second.GetString();
365	  if (config_str.empty()) {
366	    return SUCCESS;
367	  }
368	  return ParseGlobalResourceConfig(config_str);
