370	
371	Status HixlOptions::ResolveLocalCommResFromFile() {
372	  if (!global_resource_config_.has_value() || !global_resource_config_->local_comm_res_path.has_value()) {
373	    return SUCCESS;
374	  }
375	  if (local_comm_res_.has_value() && !local_comm_res_->empty()) {
376	    HIXL_EVENT("OPTION_LOCAL_COMM_RES is set, ignore local_comm_res_path file path: %s",
377	               global_resource_config_->local_comm_res_path->c_str());
378	    return SUCCESS;
379	  }
380	
381	  const std::string &path = *global_resource_config_->local_comm_res_path;
382	  char resolved_path[PATH_MAX] = {};
383	  HIXL_CHK_BOOL_RET_STATUS(realpath(path.c_str(), resolved_path) != nullptr, PARAM_INVALID,
384	                           "Call api:realpath failed, path:%s, errno=%d, errmsg=%s", path.c_str(), errno,
385	                           strerror(errno));
386	
387	  std::string content;
388	  HIXL_CHK_STATUS_RET(ReadLocalCommResFile(resolved_path, content), "Failed to read local_comm_res_path file, path:%s",
389	                      resolved_path);
390	  local_comm_res_ = std::move(content);
391	  HIXL_EVENT("Resolved local_comm_res from file successfully, path:%s, content_size:%zu bytes", resolved_path,
392	             local_comm_res_->size());
393	  return SUCCESS;
394	}
